        "K3_keff": "4/12",
        "K5_keff": "7/12",
        "K7_keff": "8/12",
    }

    all_results = {}

    for K in PANEL_SIZES:
        logger.info(f"\n{'='*70}")
        logger.info(f"PANEL SIZE K={K}")
        logger.info(f"{'='*70}")

        all_combos = list(itertools.combinations(range(len(ALL_MODELS)), K))
        logger.info(f"  C(15,{K}) = {len(all_combos)} panels")

        condition_results = {}
        raw_keff_ps = []
        raw_eta_ps = []
        valid_conditions = []

        for ds in DATASETS:
            mi_mat = np.array(mi_matrices[ds])
            for atk in ATTACKS:
                cond = f"{ds}x{atk}"
                t0 = time.time()

                panel_data = []
                for combo in all_combos:
                    jids = [ALL_MODELS[i] for i in combo]
                    if not all((ds, atk, j) in ind_asr for j in jids):
                        continue

                    if K == 3:
                        pk = "|".join(jids)
                        keff_dict = keff_precomputed.get(ds, {}).get(pk)
                        keff = keff_dict["keff"] if keff_dict else mi_based_keff(mi_mat, list(combo))
                    else:
                        keff = mi_based_keff(mi_mat, list(combo))

                    eta_max = max(ind_asr[(ds, atk, j)] for j in jids)
                    cs = {j: clean[ds][j] for j in jids}
                    ats = {j: attacked[ds][atk][j] for j in jids}
                    asr = compute_panel_asr(jids, cs, ats, pairs[ds])

                    panel_data.append({
                        "jids": jids,
                        "keff": keff,
                        "eta_max": eta_max,
                        "asr": asr,
                    })

                n_panels = len(panel_data)
                elapsed_build = time.time() - t0

                if n_panels < 10:
                    logger.warning(f"  {cond}: {n_panels} panels, skipping")
                    condition_results[cond] = {"skipped": True, "n_panels": n_panels}
                    continue

                # Expand: each panel → K rows (one per judge)
                rows = []
                for pid, pd_item in enumerate(panel_data):
                    log_asr = np.log(pd_item["asr"] + EPS)
                    log_keff = np.log(pd_item["keff"])
                    log_eta = np.log(pd_item["eta_max"] + EPS)
                    for jid in pd_item["jids"]:
                        rows.append({
                            "panel_id": f"p{pid}",
                            "judge_id": jid,
                            "log_asr": log_asr,
                            "log_keff": log_keff,
                            "log_eta": log_eta,
                        })

                df = pd.DataFrame(rows)

                t1 = time.time()
                result = fit_crossed_re(df)
                elapsed_fit = time.time() - t1

                condition_results[cond] = result
                condition_results[cond]["n_panels"] = n_panels
                condition_results[cond]["n_expanded_rows"] = len(df)

                if result.get("converged", False):
                    logger.info(
                        f"  {cond}: {n_panels} panels, {len(df)} rows | "
                        f"K_eff β={result['keff_coef']:+.4f} p={result['keff_p']:.4e}"
                        f"{'*' if result['keff_sig'] else ''} | "
                        f"η β={result['eta_coef']:+.4f} p={result['eta_p']:.4e}"
                        f"{'*' if result['eta_sig'] else ''} | "
                        f"RE_var={result['judge_re_var']:.4f} "
